package org.brightstats.desktop;
import java.util.*;import java.nio.file.*;import com.google.gson.*;import javafx.scene.Node;import javafx.scene.chart.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.FileChooser;import org.brightstats.report.SvgGraphics;
/** Additional graphics read only archived intervals and explicitly named observed matrices. */
final class ArchivedDiagnostics {
 private ArchivedDiagnostics(){}
 static TabPane create(JsonObject report){TabPane tabs=new TabPane();var results=report.getAsJsonObject("results");for(String key:List.of("fiml","ordinalSem","imputedSem","bayesianSem")){if(!results.has(key)||!results.get(key).isJsonObject())continue;var fit=results.getAsJsonObject(key);var terms=key.equals("imputedSem")?fit.getAsJsonObject("pooled").getAsJsonArray("terms"):fit.getAsJsonArray("terms");if(terms!=null&&!terms.isEmpty()){var x=new NumberAxis();x.setForceZeroInRange(false);x.setLabel("Archived estimate and pointwise interval (original parameter units)");var y=new CategoryAxis();y.setLabel("Model parameter");LineChart<Number,String> chart=new LineChart<>(x,y);chart.setAnimated(false);chart.setLegendVisible(false);chart.setTitle(key.equals("bayesianSem")?"Posterior means and equal-tail credible intervals":"Estimates and confidence intervals");List<String> labels=new ArrayList<>();int index=0;for(var value:terms){var term=value.getAsJsonObject();String name=(++index)+". "+term.get("parameter").getAsString();labels.add(name);var numbers=key.equals("bayesianSem")?term.getAsJsonObject("posterior"):term;String point=key.equals("bayesianSem")?"mean":"estimate";if(!finite(numbers,point))continue;var series=new XYChart.Series<Number,String>();series.setName(term.get("parameter").getAsString());if(finite(numbers,"lower"))series.getData().add(new XYChart.Data<>(numbers.get("lower").getAsDouble(),name,"Archived lower limit"));series.getData().add(new XYChart.Data<>(numbers.get(point).getAsDouble(),name,"Archived estimate"));if(finite(numbers,"upper"))series.getData().add(new XYChart.Data<>(numbers.get("upper").getAsDouble(),name,"Archived upper limit"));chart.getData().add(series);}y.setAutoRanging(false);y.getCategories().setAll(labels);chart.setPrefHeight(Math.max(430,80+labels.size()*35));Label note=new Label("Each interval belongs to its named estimator and configured confidence/credibility level. Parameter units can differ; do not compare length as standardized importance. Missing limits stay missing. No SE, P value or interval is reconstructed here.");note.setWrapText(true);VBox content=new VBox(9,note,chart);content.setStyle("-fx-padding:12;");VBox.setVgrow(chart,Priority.ALWAYS);add(tabs,"Parameter intervals",content);}
 if(fit.has("model")){var model=fit.getAsJsonObject("model");List<String> names=new ArrayList<>();for(var observed:model.getAsJsonArray("observed"))names.add(model.getAsJsonArray("variables").get(observed.getAsInt()).getAsString());for(String matrix:List.of("impliedCovariance","impliedCorrelation","residualCorrelation"))if(fit.has(matrix)&&fit.get(matrix).isJsonArray()&&names.size()<=150){double[][] values=new Gson().fromJson(fit.get(matrix),double[][].class);String title=switch(matrix){case "impliedCovariance"->"Fitted observed covariance";case "impliedCorrelation"->"Fitted latent-response correlation";default->"Latent-response residual correlation";};MatrixHeatmap view=new MatrixHeatmap(title,names,values);ScrollPane scroll=new ScrollPane(view);scroll.setFitToWidth(true);scroll.setFitToHeight(true);add(tabs,title,scroll);}}
 }VisualSelection.attach(tabs,report.getAsJsonObject("project"));ChartTools.install(tabs);return tabs;}
 static boolean finite(JsonObject value,String key){if(!value.has(key)||value.get(key).isJsonNull())return false;try{return Double.isFinite(value.get(key).getAsDouble());}catch(RuntimeException invalid){return false;}}
 static void add(TabPane tabs,String title,Node node){Tab tab=new Tab(title,node);tab.setClosable(false);tabs.getTabs().add(tab);}
 static void show(Node owner,JsonObject report){TabPane tabs=create(report);tabs.addEventHandler(VisualSelection.TYPE,e->{owner.fireEvent(new VisualSelection.Selection(e.frame,e.label,e.rows,e.columns));e.consume();});if(tabs.getTabs().isEmpty()){Alert empty=new Alert(Alert.AlertType.INFORMATION,"This method has no compatible archived interval/matrix graphic. Its existing diagnostic tabs remain available.",ButtonType.OK);empty.initOwner(owner.getScene().getWindow());empty.showAndWait();return;}Dialog<Void> dialog=new Dialog<>();dialog.initOwner(owner.getScene().getWindow());dialog.setTitle("Archived statistical diagnostics");dialog.setResizable(true);Button export=new Button("Export selected graphic as SVG");export.setOnAction(e->{FileChooser chooser=new FileChooser();chooser.setTitle("Save source-bearing diagnostic graphic");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("SVG graphic","*.svg"));chooser.setInitialFileName("bright-stats-diagnostic.svg");var file=chooser.showSaveDialog(dialog.getDialogPane().getScene().getWindow());if(file!=null)try{String svg=SvgGraphics.charts(tabs.getSelectionModel().getSelectedItem().getContent(),tabs.getSelectionModel().getSelectedItem().getText());Files.writeString(file.toPath(),svg,StandardOpenOption.CREATE_NEW);}catch(Exception problem){Alert error=new Alert(Alert.AlertType.ERROR,"Graphic was not saved: "+problem.getMessage(),ButtonType.OK);error.initOwner(dialog.getDialogPane().getScene().getWindow());error.showAndWait();}});BorderPane content=new BorderPane(tabs);content.setBottom(export);content.setPrefSize(1000,700);dialog.getDialogPane().setContent(content);dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);dialog.showAndWait();}
}
